package com.ethk3.novaonepro.strategyv2;
import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import com.ethk3.novaonepro.BuildConfig;import java.util.*;

/** Generation-private research input. Reads original measures, never chart caches or formal outcomes. */
public final class ResearchContextR30R1 {
 public static final String MARK=";R1REF[";public final String datasetHash;public final long revision;
 private final Map<String,Map<String,Object>> frames=new LinkedHashMap<>();private final Map<String,String> runs=new LinkedHashMap<>();private final LinkedHashSet<String> used=new LinkedHashSet<>();
 private ResearchContextR30R1(String dataset,long revision){datasetHash=dataset;this.revision=revision;}
 @SuppressWarnings("unchecked") public static ResearchContextR30R1 read(SQLiteDatabase db,EvalContextR27 c){long revision=ResearchInputPinR30R1.revision(db,c.data.datasetHash);ResearchContextR30R1 out=new ResearchContextR30R1(c.data.datasetHash,revision);try(Cursor q=db.rawQuery("SELECT m.measure_key,m.payload_json,r.run_id,r.summary_json FROM r30r1_research_measure m JOIN r30r1_analysis_run r ON r.run_id=m.run_id WHERE r.role='SELECT' AND r.status='COMMITTED' AND r.dataset_hash=? AND r.source_revision=? AND r.source_commit=? AND m.kind IN ('STRUCTURE_STATE','STRUCTURE_FORECAST_ERROR','POSITION_COMPATIBILITY','MOLECULE_SYNERGY','DRIFT_REPLAY_VALUE') ORDER BY r.recorded_at DESC,r.run_id LIMIT 32",new String[]{c.data.datasetHash,String.valueOf(revision),BuildConfig.SOURCE_COMMIT_R26})){while(q.moveToNext()){if(out.frames.containsKey(q.getString(0))||!ResearchStoreR30R1.currentSource(BuildConfig.SOURCE_COMMIT_R26,q.getString(3)))continue;Map<String,Object> source=(Map<String,Object>)JsonR27.parse(q.getString(1));if(!(source.get("frame") instanceof Map))continue;Map<String,Object> frame=(Map<String,Object>)source.get("frame");if(!"SELECT".equals(frame.get("role"))||!c.data.datasetHash.equals(frame.get("datasetHash")))continue;out.frames.put(q.getString(0),frame);out.runs.put(q.getString(0),q.getString(2));}}return out;}
 public void begin(){used.clear();}void use(String view){String run=runs.get(view);if(run!=null)used.add(run);}
 @SuppressWarnings("unchecked") public int window(StatsR27.SplitMix r,int fallback){Map<String,Object> errors=frames.get("R02");if(errors==null||r.chance(.25))return fallback;List<Integer> supported=new ArrayList<>();for(Object o:(List<?>)errors.get("cells")){Map<String,Object> row=(Map<String,Object>)o;Object lower=row.get("lower95");if(lower instanceof Number&&((Number)lower).doubleValue()>0){int w=((Number)row.get("window")).intValue();if(!supported.contains(w))supported.add(w);}}if(supported.isEmpty())return fallback;use("R02");return supported.get(r.nextInt(supported.size()));}
 @SuppressWarnings("unchecked") public int[] cross(StatsR27.SplitMix r,int target){Map<String,Object> frame=frames.get("R03");if(frame==null||r.chance(.25))return null;Object raw=frame.get("directedLag");if(!(raw instanceof Map))return null;Map<String,Object> tensor=(Map<String,Object>)raw;List<?> values=(List<?>)tensor.get("values"),support=(List<?>)tensor.get("support");if(values==null||support==null||target<1||target>10)return null;List<int[]> eligible=new ArrayList<>();List<?> row=(List<?>)values.get(target-1),n=(List<?>)support.get(target-1);for(int source=1;source<=10;source++)for(int k=0;k<2;k++){int at=(source-1)*4+k;if(row.get(at) instanceof Number&&n.get(at) instanceof Number&&((Number)n.get(at)).longValue()>=200&&((Number)row.get(at)).doubleValue()>0)eligible.add(new int[]{source,k+1});}if(eligible.isEmpty())return null;use("R03");return eligible.get(r.nextInt(eligible.size()));}
 @SuppressWarnings("unchecked") public PolicyAstR27.Node molecule(StatsR27.SplitMix r){Map<String,Object> frame=frames.get("R07");if(frame==null||r.chance(.25))return null;for(Object o:(List<?>)frame.get("points")){Map<String,Object> p=(Map<String,Object>)o;if(p.get("lower") instanceof Number&&((Number)p.get("lower")).doubleValue()>0&&p.get("parent") instanceof String){PolicySpecR27 parent=PolicySpecR27.parse((String)p.get("parent"));if(parent.ast.depth()<=3&&parent.ast.size()<=16){use("R07");return parent.ast;}}}return null;}
 public PolicySpecR27 annotate(PolicySpecR27 p){if(p==null||used.isEmpty())return p;PolicySpecR27.Meta m=p.meta;if(m==null)throw new IllegalStateException("RESEARCH_PROVENANCE_META_REQUIRED");String refs=String.join(",",used);return p.withMeta(new PolicySpecR27.Meta(m.idea,m.operator,m.parents,m.generation,m.seed,m.reason+MARK+refs+"]"));}
 public static List<String> references(PolicySpecR27 p){if(p==null||p.meta==null||p.meta.reason==null)return Collections.emptyList();String reason=p.meta.reason;int start=reason.lastIndexOf(MARK);if(start<0)return Collections.emptyList();int end=reason.indexOf(']',start+MARK.length());if(end<0)throw new IllegalStateException("RESEARCH_REFERENCE_FORMAT");List<String> ids=Arrays.asList(reason.substring(start+MARK.length(),end).split(","));if(ids.size()>4)throw new IllegalStateException("RESEARCH_REFERENCE_BUDGET");for(String id:ids)ResearchContractR30R1.sha(id);return ids;}
 static String proposal(PolicySpecR27 p,String dataset,List<String> refs){return StatsR27.sha256("RESEARCH_HYPOTHESIS1|"+dataset+'|'+p.policyHash()+'|'+String.join(",",refs));}
 public static String stage(ResearchWriteQueueR27.Batch b,PolicySpecR27 p,String dataset,long revision,long now){List<String> refs=references(p);if(refs.isEmpty())return null;String id=proposal(p,dataset,refs);Map<String,Object> payload=new LinkedHashMap<>();payload.put("candidate",p.fullJson());payload.put("candidateHash",p.policyHash());payload.put("sourceRuns",refs);payload.put("consumer",p.meta.idea);payload.put("role","SELECT");String json=JsonR27.write(payload);b.guardBefore(db->{ResearchInputPinR30R1.require(db,dataset,revision);for(String ref:refs)try(Cursor q=db.rawQuery("SELECT role,source_revision,source_commit,summary_json FROM r30r1_analysis_run WHERE run_id=? AND dataset_hash=? AND status='COMMITTED'",new String[]{ref,dataset})){if(!q.moveToFirst()||!"SELECT".equals(q.getString(0))||q.getLong(1)!=revision||!ResearchStoreR30R1.currentSource(q.getString(2),q.getString(3)))throw new ResearchStoreR30R1.StaleResearch();}return 0;});b.add("INSERT OR IGNORE INTO r30r1_proposal VALUES(?,?,?,?,?,?,?,?,?)",id,refs.get(0),p.meta.parents.isEmpty()?StatsR27.sha256("NO_PARENT_NEW_HYPOTHESIS"):p.meta.parents.get(0),"SUPPORTED_RESEARCH_HYPOTHESIS",json,StatsR27.sha256(json),"READY","Research source consumed to construct exact typed candidate; original birth gate and independent confirmation remain",now);return id;}
}
